func runTimeline(args []string) int {
	fs := newFlagSet("timeline")
	bucketMinutes := fs.Int("bucket-minutes", 0, "width of each time bucket in minutes")
	topN := fs.Int("top-n", 3, "maximum number of top threats to include per bucket")
	if !parseFlags(fs, args) {
		return 1
	}
	if !isFlagSet(fs, "bucket-minutes") {
		fmt.Fprintln(os.Stderr, "missing required flag: --bucket-minutes")
		return 1
	}
	if *bucketMinutes <= 0 {
		fmt.Fprintf(os.Stderr, "invalid --bucket-minutes: must be a positive integer\n")
		return 1
	}
	if *topN < 0 {
		fmt.Fprintf(os.Stderr, "invalid --top-n: must be non-negative\n")
		return 1
	}

	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
	lineNo := 0
	var threats []map[string]interface{}
	for scanner.Scan() {
		lineNo++
		line := scanner.Text()
		if line == "" {
			continue
		}
		var threat map[string]interface{}
		if err := json.Unmarshal([]byte(line), &threat); err != nil {
			fmt.Fprintf(os.Stderr, "line %d: %v\n", lineNo, err)
			return 2
		}
		threats = append(threats, threat)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "error reading input: %v\n", err)
		return 2
	}

	bucketSeconds := int64(*bucketMinutes) * 60
	buckets := make(map[int64][]map[string]interface{})
	var bucketStarts []int64
	for _, threat := range threats {
		refTime := threatSortTime(threat)
		var refUnix int64
		if !refTime.IsZero() {
			refUnix = refTime.Unix()
		}
		start := (refUnix / bucketSeconds) * bucketSeconds
		if _, ok := buckets[start]; !ok {
			bucketStarts = append(bucketStarts, start)
		}
		buckets[start] = append(buckets[start], threat)
	}

	sort.Slice(bucketStarts, func(i, j int) bool { return bucketStarts[i] < bucketStarts[j] })

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for _, start := range bucketStarts {
		bucketThreats := buckets[start]
		startTime := time.Unix(start, 0).UTC()
		endTime := startTime.Add(time.Duration(*bucketMinutes) * time.Minute)
		b := buildTimelineBucket(bucketThreats, startTime, endTime, *bucketMinutes, *topN)
		data, err := json.Marshal(b)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error marshalling bucket: %v\n", err)
			return 2
		}
		writer.Write(data)
		writer.WriteByte('\n')
	}

	return 0
}

func buildTimelineBucket(threats []map[string]interface{}, startTime time.Time, endTime time.Time, bucketMinutes int, topN int) timelineBucket {
	n := len(threats)
	b := timelineBucket{
		BucketStart:       startTime.Format(time.RFC3339),
		BucketEnd:         endTime.Format(time.RFC3339),
		ThreatCount:       n,
		TypeDistribution:  map[string]int{},
		SeverityHistogram: map[string]int{"none": 0, "low": 0, "medium": 0, "high": 0, "critical": 0},
		UniqueActors:     []string{},
		TopThreats:        []map[string]interface{}{},
	}

	if n == 0 {
		return b
	}

	var sumRisk, maxRisk, minRisk float64
	typeCounts := map[string]int{}
	actorSet := map[string]bool{}
	risks := make([]float64, 0, n)
	for _, threat := range threats {
		risk, _ := getFloat(threat, "enriched_risk_score")
		risks = append(risks, risk)
		sumRisk += risk
		if risk > maxRisk {
			maxRisk = risk
		}
		if risk < minRisk {
			minRisk = risk
		}
		if tt, ok := getString(threat, "threat_type"); ok {
			typeCounts[tt]++
		}
		if sev, ok := getString(threat, "ioc_severity"); ok {
			if _, exists := b.SeverityHistogram[sev]; exists {
				b.SeverityHistogram[sev]++
			}
		}
		if actors, ok := getStringSlice(threat, "threat_actors"); ok {
			for _, actor := range actors {
				if actor != "" {
					actorSet[actor] = true
				}
			}
		}
	}
	b.AvgRisk = round2(sumRisk / float64(n))
	b.MaxRisk = round2(maxRisk)
	b.MinRisk = round2(minRisk)

	mean := sumRisk / float64(n)
	var variance float64
	for _, risk := range risks {
		diff := risk - mean
		variance += diff * diff
	}
	if n == 1 {
		variance = 0.0
	} else {
		variance /= float64(n)
	}
	b.RiskStdDev = round2(math.Sqrt(variance))

	b.DominantType = dominantThreatType(typeCounts)
	b.TypeDistribution = typeCounts

	b.UniqueActors = nonNilStrings(sortedUniqueStringsFromSet(actorSet))

	b.EscalationIndex = round2(timelineEscalationIndex(threats))
	b.RiskTrend = round2(timelineRiskTrend(threats, startTime))
	b.BurstScore = round2(timelineBurstScore(threats))

	sortedTop := make([]map[string]interface{}, len(threats))
	copy(sortedTop, threats)
	sort.SliceStable(sortedTop, func(i, j int) bool {
		ri, _ := getFloat(sortedTop[i], "enriched_risk_score")
		rj, _ := getFloat(sortedTop[j], "enriched_risk_score")
		if ri != rj {
			return ri > rj
		}
		ti, tj := threatSortTime(sortedTop[i]), threatSortTime(sortedTop[j])
		if !ti.Equal(tj) {
			return ti.Before(tj)
		}
		tta, _ := getString(sortedTop[i], "threat_type")
		ttb, _ := getString(sortedTop[j], "threat_type")
		return tta < ttb
	})
	if topN < len(sortedTop) {
		sortedTop = sortedTop[:topN]
	}
	b.TopThreats = sortedTop

	return b
}

func dominantThreatType(counts map[string]int) string {
	var keys []string
	for k := range counts {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	dominant := ""
	maxCount := -1
	for _, k := range keys {
		if counts[k] > maxCount {
			maxCount = counts[k]
			dominant = k
		}
	}
	return dominant
}

func timelineSeverityRank(sev string) int {
	switch sev {
	case "none":
		return 0
	case "low":
		return 1
	case "medium":
		return 2
	case "high":
		return 3
	case "critical":
		return 4
	default:
		return -1
	}
}

func timelineEscalationIndex(threats []map[string]interface{}) float64 {
	n := len(threats)
	if n < 2 {
		return 0.0
	}
	ordered := make([]map[string]interface{}, len(threats))
	copy(ordered, threats)
	sort.SliceStable(ordered, func(i, j int) bool {
		ti, tj := threatSortTime(ordered[i]), threatSortTime(ordered[j])
		if !ti.Equal(tj) {
			return ti.Before(tj)
		}
		tta, _ := getString(ordered[i], "threat_type")
		ttb, _ := getString(ordered[j], "threat_type")
		return tta < ttb
	})

	positiveSum := 0.0
	for i := 0; i < len(ordered)-1; i++ {
		rankI := timelineSeverityRank(getStringDefault(ordered[i], "ioc_severity"))
		rankJ := timelineSeverityRank(getStringDefault(ordered[i+1], "ioc_severity"))
		if rankI < 0 {
			rankI = 0
		}
		if rankJ < 0 {
			rankJ = 0
		}
		delta := rankJ - rankI
		if delta > 0 {
			positiveSum += float64(delta)
		}
	}
	return positiveSum / (4.0 * float64(n-1))
}

func timelineRiskTrend(threats []map[string]interface{}, startTime time.Time) float64 {
	n := len(threats)
	if n < 2 {
		return 0.0
	}
	xs := make([]float64, n)
	ys := make([]float64, n)
	for i, threat := range threats {
		refTime := threatSortTime(threat)
		xs[i] = refTime.Sub(startTime).Minutes()
		ys[i], _ = getFloat(threat, "enriched_risk_score")
	}
	sameX := true
	for i := 1; i < n; i++ {
		if xs[i] != xs[0] {
			sameX = false
			break
		}
	}
	if sameX {
		return 0.0
	}
	var sumX, sumY, sumXY, sumXX2 float64
	for i := 0; i < n; i++ {
		sumX += xs[i]
		sumY += ys[i]
		sumXY += xs[i] * ys[i]
		sumXX2 += xs[i] * xs[i]
	}
	denom := float64(n)*sumXX2 - sumX*sumX
	if denom == 0 {
		return 0.0
	}
	return (float64(n)*sumXY - sumX*sumY) / denom
}

func timelineBurstScore(threats []map[string]interface{}) float64 {
	n := len(threats)
	if n < 2 {
		return 0.0
	}
	times := make([]float64, n)
	for i, threat := range threats {
		refTime := threatSortTime(threat)
		times[i] = float64(refTime.Unix()) / 60.0
	}
	sum := 0.0
	pairs := 0
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			sum += 1.0 / (1.0 + math.Abs(times[i]-times[j]))
			pairs++
		}
	}
	return sum / float64(pairs)
}

func getStringDefault(m map[string]interface{}, key string) string {
	if v, ok := getString(m, key); ok {
		return v
	}
	return ""
}
